  sanitizeNarration(raw,fallback=''){
    let text=String(raw??'').replace(/\r/g,'').trim();
    if(!text)return fallback;
    const endMarkers=['--- FIM DO CONTEXTO','FIM DO CONTEXTO','--- END OF CONTEXT','END OF CONTEXT'];
    for(const marker of endMarkers){const i=text.toUpperCase().indexOf(marker);if(i>=0)text=text.slice(i+marker.length).trim()}
    text=text.replace(/^\s*[“"']?/,'').replace(/[”"']?\s*$/,'').trim();
    const metaMarkers=[
      'INSTRUÇÃO DE NARRAÇÃO','INSTRUCAO DE NARRACAO','CONTEXTO DO MESTRE','WORLD_STATE_FOR_DRAMATIZATION',
      'NARRATIVE_POLICY','PRESENTATION.COVERAGE','SYSTEM PROMPT','PROMPT DO SISTEMA','FIM DO CONTEXTO'
    ];
    const upper=text.toUpperCase();
    if(metaMarkers.some(x=>upper.includes(x)))return fallback;
    const badPhrases=[
      'a orientação começa pelo que é seguro afirmar','o mapa não confirma permanece em aberto',
      'a apresentação não transforma ausência de dados','não despeje este contexto como relatório',
      'não determine emoções ou decisões internas do personagem do jogador'
    ];
    const lower=text.toLowerCase();
    if(badPhrases.some(x=>lower.includes(x)))return fallback;
    text=text.replace(/^\s*(?:RESPOSTA|NARRAÇÃO|NARRACAO)\s*:\s*/i,'').trim();
    return text.length>=40?text:fallback;
  }
